 ],
}
for path, keys in checks.items():
    if path.endswith("#neg"):
        continue
    text = open(path, encoding="utf-8").read()
    neg = checks.get(path + "#neg", [])
    missing = [k for k in keys if k not in text]
    unwanted = [k for k in neg if k in text]
    print(path, "OK" if not missing and not unwanted else f"missing={missing} unwanted={unwanted}")
